from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
from concurrent.futures import ThreadPoolExecutor,as_completed
from urllib.parse import urlparse
import hashlib,json,re,requests
P=Path.cwd();R=P/'reports/research/510300_electricity_original_publication_state_v1'
now=lambda:datetime.now(ZoneInfo('Asia/Shanghai')).isoformat()
if (R/'原报告请求账本.json').exists():raise RuntimeError('原报告采集账本已存在，禁止重发')
c=json.loads((R/'目录实际全国用电量标题锚点_动态补充.json').read_text(encoding='utf-8'))
rows=[];excluded=[]
for v in c:
 t=v.get('directory_publishTime')
 if t: day=t[:10]
 else:
  m=re.search(r'/(\d{4})-(\d{2})/(\d{2})/',v['url'])
  day='-'.join(m.groups()) if m else None
 if day and '2018-01-01'<=day<='2026-01-31':
  v['navigation_date_for_request_only']=day;rows.append(v)
 else:excluded.append({'url':v['url'],'title':v['title'],'directory_date_or_url_route_date':day,'reason':'固定统计期原文采集导航时间外，不把目录日期认证首版'})
if len(rows)>100:raise RuntimeError('实际原对象多于原预算，停止不挑有利样本')
existing=json.loads((P/'reports/research/510300_electricity_physical_quantity_source_qualification_v1/原公开收件_全部.json').read_text(encoding='utf-8-sig'))
print('已有收件结构',type(existing).__name__,flush=True)
if isinstance(existing,dict):
 objects=existing.get('requests') or existing.get('receipts') or existing.get('objects') or []
else:objects=existing
if not objects:raise RuntimeError('复用账本结构未建立，停止')
print('已有首记录键',list(objects[0]),flush=True)
lookup={x.get('requested_url') or x.get('url'):x for x in objects}
selected=[];reuse=[];todo=[]
for v in rows:
 old=lookup.get(v['url'])
 if old and old.get('status_code')==200:
  oldpath=old.get('raw_path') or old.get('path')
  oldsha=old.get('sha256') or old.get('raw_sha256')
  if not oldpath or not oldsha:raise RuntimeError('旧收件原路径或hash未定位')
  b=(P/oldpath).read_bytes()
  if hashlib.sha256(b).hexdigest()!=oldsha:raise RuntimeError('旧收件哈希不一致')
  z={**v,'raw_path':oldpath,'sha256':oldsha,'bytes':len(b),'received_at':old.get('received_at'),'reused':True,'status_code':200}
  reuse.append(z)
 else:todo.append(v)
 selected.append(v)
reg={'registered_at':now(),'actual_report_urls':selected,'excluded_outside_fixed_navigation_range':excluded,'requested_range_is_navigation_only':True,'new_original_gets':len(todo),'reused_original_reports':len(reuse),'max_gets_original':100,'original_candidates_sha256':hashlib.sha256((R/'目录实际全国用电量标题锚点_动态补充.json').read_bytes()).hexdigest(),'source_gate_or_model_unchanged':True}
def save(n,v):(R/n).write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
save('04_实际原报告请求清单_请求前.json',reg)
def fetch(v):
 u=v['url'];tag=hashlib.sha256(u.encode()).hexdigest()[:16];q=R/'raw'/('report_'+tag+'.html')
 z={**v,'requested_url':u,'method':'GET','started_at':now(),'automatic_redirects':False,'retries':0,'credentials_used':False,'reused':False}
 try:
  with requests.Session() as sess:
   sess.trust_env=False
   a=sess.get(u,timeout=(10,25),allow_redirects=False,headers={'User-Agent':'Mozilla/5.0 (compatible; public historical research)','Accept':'text/html'})
   q.write_bytes(a.content)
   z.update({'status_code':a.status_code,'received_at':now(),'response_url':a.url,'redirect_location':a.headers.get('Location'),'bytes':len(a.content),'sha256':hashlib.sha256(a.content).hexdigest(),'raw_path':str(q.relative_to(P)).replace('\\','/'),'content_type':a.headers.get('Content-Type'),'http_date':a.headers.get('Date')})
 except Exception as e:z.update({'status_code':None,'received_at':now(),'bytes':0,'error_type':type(e).__name__,'error':str(e)})
 return z
ledger=[]
with ThreadPoolExecutor(max_workers=4) as ex:
 for fut in as_completed([ex.submit(fetch,v) for v in todo]):
  z=fut.result();ledger.append(z);save('原报告请求账本.json',ledger)
  if z['status_code']!=200 or len(ledger)%10==0 or len(ledger)==len(todo):print('原报告收件进度',len(ledger),'/',len(todo),'最近HTTP',z['status_code'],flush=True)
save('全部原报告收件与复用.json',reuse+ledger)
print(json.dumps({'新原报告GET':len(ledger),'新原报告HTTP200':sum(x['status_code']==200 for x in ledger),'新原报告字节':sum(x.get('bytes',0) for x in ledger),'复用原报告':len(reuse),'全部原对象':len(reuse)+len(ledger),'目录导航最早日期':min(v['navigation_date_for_request_only'] for v in rows),'目录导航最晚日期':max(v['navigation_date_for_request_only'] for v in rows),'原完整支持最早需要':'2018-12-06'},ensure_ascii=False))
